SELECT (SELECT channel FROM marketing_campaigns m WHERE m.campaign_id = ws.campaign_id) AS ch, COUNT(session_id), SUM(CASE WHEN added_to_cart THEN 1 ELSE 0 END), SUM(CASE WHEN converted_order_id IS NOT NULL THEN 1 ELSE 0 END) FROM web_sessions ws WHERE ws.campaign_id IS NOT NULL AND ws.started_at_utc >= TIMESTAMP '2025-04-01 00:00:00' - INTERVAL 6 HOUR AND ws.started_at_utc < TIMESTAMP '2025-06-30 00:00:00' + INTERVAL 18 HOUR GROUP BY 1
